-- Unknown historical profession is never inferred from the current profile.
ALTER TABLE consultation_requests ADD COLUMN profession_snapshot TEXT CHECK(profession_snapshot IN('PSYCHOLOGIST','COUNSELOR','PSYCHIATRIST'));
CREATE OR REPLACE FUNCTION clinic_booking_immutable() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.clinic_governed AND(ROW(NEW.requester_user_id,NEW.professional_user_id,NEW.availability_slot_id,NEW.scheduled_at,NEW.ends_at,NEW.consultation_mode,NEW.price_units,NEW.commission_units,NEW.provider_fee_units,NEW.currency,NEW.policy_id,NEW.terms_snapshot,NEW.booking_key,NEW.clinic_governed,NEW.profession_snapshot) IS DISTINCT FROM ROW(OLD.requester_user_id,OLD.professional_user_id,OLD.availability_slot_id,OLD.scheduled_at,OLD.ends_at,OLD.consultation_mode,OLD.price_units,OLD.commission_units,OLD.provider_fee_units,OLD.currency,OLD.policy_id,OLD.terms_snapshot,OLD.booking_key,OLD.clinic_governed,OLD.profession_snapshot)) THEN RAISE EXCEPTION 'Agreed clinic booking is immutable'; END IF;RETURN NEW; END $$;
